"use client";

import { useState } from "react";
import CollectionsPane from "./CollectionsPane";

const APP_FONT = '"Avenir Next", "Segoe UI", sans-serif';
const MONO_FONT = "ui-monospace, SFMono-Regular, Menlo, monospace";
const HTTP_METHODS = ["GET", "POST", "PUT", "PATCH", "DELETE"];
const REQUEST_TABS = ["Params", "Headers", "Body", "cURL", "Import cURL"];
const TABLE_COLUMNS = "44px 1fr 1fr 1fr 46px";

function createEmptyRow() {
    return { enabled: true, key: "", value: "", description: "" };
}

function escapeSingleQuotes(value) {
    return String(value).replace(/'/g, "'\\''");
}

function formatJsonIfPossible(value) {
    const text = String(value ?? "").trim();
    if (!text) return "{}";

    try {
        return JSON.stringify(JSON.parse(text), null, 2);
    } catch {
        return value;
    }
}

export default function ApiPlaygroundPage() {
    const [method, setMethod] = useState("GET");
    const [url, setUrl] = useState("http://localhost:8081/api/hello");
    const [paramsRows, setParamsRows] = useState([createEmptyRow()]);
    const [headerRows, setHeaderRows] = useState([
        { enabled: true, key: "Content-Type", value: "application/json", description: "" },
    ]);
    const [bodyInput, setBodyInput] = useState("{}");
    const [activeTab, setActiveTab] = useState("Params");
    const [importCurlText, setImportCurlText] = useState("");
    const [importMessage, setImportMessage] = useState("");
    const [showSuccessToast, setShowSuccessToast] = useState(false);
    const canSendBody = method !== "GET" && method !== "DELETE";

    const updateRow = (setter, rowIndex, field, fieldValue) => {
        setter((prev) => prev.map((row, index) => (index === rowIndex ? { ...row, [field]: fieldValue } : row)));
    };

    const addRow = (setter) => {
        setter((prev) => [...prev, createEmptyRow()]);
    };

    const removeRow = (setter, rowIndex) => {
        setter((prev) => prev.filter((_, index) => index !== rowIndex));
    };

    const queryParams = paramsRows
        .filter((row) => row.enabled && row.key.trim())
        .map((row) => `${encodeURIComponent(row.key)}=${encodeURIComponent(row.value)}`)
        .join("&");

    const requestUrlPreview = queryParams ? `${url}${url.includes("?") ? "&" : "?"}${queryParams}` : url;

    const curlHeaders = headerRows
        .filter((row) => row.enabled && row.key.trim())
        .map((row) => `--header '${escapeSingleQuotes(row.key)}: ${escapeSingleQuotes(row.value)}'`)
        .join(" ");

    const curlBody = canSendBody && bodyInput.trim()
        ? `--data '${escapeSingleQuotes(bodyInput)}'`
        : "";

    const curlCommand = [
        `curl --location --request ${method}`,
        `'${escapeSingleQuotes(requestUrlPreview)}'`,
        curlHeaders,
        curlBody,
    ]
        .filter(Boolean)
        .join(" \n");

    const responsePreview = `{
  "message": "Response will appear here after you connect request execution.",
  "hint": "UI section is ready in Postman-style layout."
}`;

    const parseCurlAndApply = () => {
        const raw = importCurlText.trim();
        if (!raw) {
            setImportMessage("Paste a cURL command first.");
            return;
        }

        setImportMessage("");

        const normalized = raw.replace(/\\\s*\n/g, " ").replace(/\s+/g, " ").trim();

        const methodMatch = normalized.match(/(?:--request|-X)\s+([A-Za-z]+)/i);

        let parsedUrl = "";
        const quotedUrlMatch = normalized.match(/'((?:https?:\/\/)[^']+)'|"((?:https?:\/\/)[^"]+)"/i);
        if (quotedUrlMatch) {
            parsedUrl = quotedUrlMatch[1] || quotedUrlMatch[2] || "";
        } else {
            const plainUrlMatch = normalized.match(/(https?:\/\/\S+)/i);
            parsedUrl = plainUrlMatch?.[1] || "";
        }

        if (parsedUrl) {
            try {
                const parsed = new URL(parsedUrl);
                setUrl(`${parsed.origin}${parsed.pathname}`);

                const nextParams = Array.from(parsed.searchParams.entries()).map(([key, value]) => ({
                    enabled: true,
                    key,
                    value,
                    description: "",
                }));
                setParamsRows(nextParams.length > 0 ? nextParams : [createEmptyRow()]);
            } catch {
                setUrl(parsedUrl);
            }
        }

        const headerMatches = [...normalized.matchAll(/--header\s+(?:'([^']*)'|"([^"]*)"|([^\s]+))/gi)];
        const parsedHeaders = headerMatches
            .map((match) => match[1] || match[2] || match[3] || "")
            .map((headerLine) => {
                const separatorIndex = headerLine.indexOf(":");
                if (separatorIndex === -1) return null;
                return {
                    enabled: true,
                    key: headerLine.slice(0, separatorIndex).trim(),
                    value: headerLine.slice(separatorIndex + 1).trim(),
                    description: "",
                };
            })
            .filter(Boolean);

        setHeaderRows(
            parsedHeaders.length > 0
                ? parsedHeaders
                : [createEmptyRow()]
        );

        const bodyMatch = normalized.match(/(?:--data-raw|--data-binary|--data)\s+(?:'([^']*)'|"([^"]*)"|([^\s]+))/i);
        const parsedBody = bodyMatch ? (bodyMatch[1] || bodyMatch[2] || bodyMatch[3] || "") : "";
        setBodyInput(formatJsonIfPossible(parsedBody || "{}"));

        const parsedMethod = (methodMatch?.[1] || (parsedBody ? "POST" : "GET")).toUpperCase();
        if (HTTP_METHODS.includes(parsedMethod)) {
            setMethod(parsedMethod);
        }

        setImportCurlText("");
        setImportMessage("");
        setShowSuccessToast(true);
        setTimeout(() => setShowSuccessToast(false), 2500);
        setActiveTab("Params");
    };

    return (
        <main
            style={{
                height: "100vh",
                boxSizing: "border-box",
                paddingTop: "28px",
                paddingRight: "28px",
                paddingBottom: "28px",
                paddingLeft: "28px",
                color: "#23272f",
                fontFamily: APP_FONT,
                overflow: "hidden",
            }}
        >
            {showSuccessToast && (
                <div
                    style={{
                        position: "fixed",
                        top: 18,
                        right: 20,
                        zIndex: 1200,
                        background: "#e8f8ee",
                        border: "1px solid #9fd3b2",
                        color: "#135c32",
                        borderRadius: 10,
                        padding: "10px 12px",
                        fontSize: 13,
                        fontWeight: 700,
                        boxShadow: "0 12px 28px rgba(15, 23, 42, 0.16)",
                    }}
                >
                    Imported cURL successfully.
                </div>
            )}

            <div
                style={{
                    display: "flex",
                    alignItems: "stretch",
                    gap: 14,
                    height: "100%",
                    overflowX: "hidden",
                    overflowY: "hidden",
                }}
            >
                <CollectionsPane />

                <section
                    style={{
                        flex: 1,
                        minWidth: 0,
                        height: "100%",
                        display: "flex",
                        flexDirection: "column",
                        background: "#ffffff",
                        border: "1px solid #dbe5f1",
                        borderRadius: 12,
                        paddingTop: "10px",
                        paddingRight: "20px",
                        paddingBottom: "20px",
                        paddingLeft: "20px",
                        boxShadow: "0 8px 24px rgba(15, 23, 42, 0.06)",
                        overflow: "hidden",
                    }}
                >

                    <div style={{ display: "flex", gap: 10, alignItems: "center" }}>
                        <select
                            value={method}
                            onChange={(e) => setMethod(e.target.value)}
                            style={{
                                border: "1px solid #c7d3e7",
                                borderRadius: 8,
                                padding: "10px",
                                fontWeight: 700,
                                color: "#0b4f6c",
                                background: "#f7fbff",
                            }}
                        >
                            {HTTP_METHODS.map((httpMethod) => (
                                <option key={httpMethod} value={httpMethod}>
                                    {httpMethod}
                                </option>
                            ))}
                        </select>

                        <input
                            value={url}
                            onChange={(e) => setUrl(e.target.value)}
                            placeholder="Enter request URL"
                            style={{
                                flex: 1,
                                border: "1px solid #c7d3e7",
                                borderRadius: 8,
                                padding: "10px 12px",
                                fontSize: 14,
                            }}
                        />

                    </div>

                    <div style={{ marginTop: 8, fontSize: 12, color: "#607089" }}>
                        Request URL: {requestUrlPreview}
                    </div>

                    <div style={{ marginTop: 12, display: "flex", gap: 8, borderBottom: "1px solid #dbe5f1", paddingBottom: 8 }}>
                        {REQUEST_TABS.map((tab) => {
                            const isActive = activeTab === tab;

                            return (
                                <button
                                    key={tab}
                                    type="button"
                                    onClick={() => setActiveTab(tab)}
                                    style={{
                                        border: isActive ? "1px solid #b9e1ef" : "1px solid #dbe5f1",
                                        background: isActive ? "#eaf7fc" : "#f8fafc",
                                        color: isActive ? "#0b4f6c" : "#44516b",
                                        borderRadius: 8,
                                        padding: "8px 12px",
                                        fontWeight: 700,
                                        cursor: "pointer",
                                    }}
                                >
                                    {tab}
                                </button>
                            );
                        })}
                    </div>

                    {activeTab === "Params" && (
                        <div style={{ marginTop: 12 }}>
                            <div
                                style={{
                                    border: "1px solid #c7d3e7",
                                    borderRadius: 8,
                                    overflow: "hidden",
                                    background: "#fff",
                                    fontSize: 12,
                                }}
                            >
                                <div style={{ display: "grid", gridTemplateColumns: TABLE_COLUMNS, background: "#f7fbff", fontWeight: 700, color: "#44516b" }}>
                                    <div style={{ padding: "8px" }}>On</div>
                                    <div style={{ padding: "8px" }}>Key</div>
                                    <div style={{ padding: "8px" }}>Value</div>
                                    <div style={{ padding: "8px" }}>Description</div>
                                    <div style={{ padding: "8px" }} />
                                </div>

                                <div style={{ maxHeight: "36vh", overflowY: "auto" }}>
                                    {paramsRows.map((row, rowIndex) => (
                                        <div key={`param-${rowIndex}`} style={{ display: "grid", gridTemplateColumns: TABLE_COLUMNS, borderTop: "1px solid #edf2f8" }}>
                                            <div style={{ padding: "8px" }}>
                                                <input
                                                    type="checkbox"
                                                    checked={row.enabled}
                                                    onChange={(e) => updateRow(setParamsRows, rowIndex, "enabled", e.target.checked)}
                                                />
                                            </div>
                                            <input
                                                value={row.key}
                                                onChange={(e) => updateRow(setParamsRows, rowIndex, "key", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <input
                                                value={row.value}
                                                onChange={(e) => updateRow(setParamsRows, rowIndex, "value", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <input
                                                value={row.description}
                                                onChange={(e) => updateRow(setParamsRows, rowIndex, "description", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <button
                                                type="button"
                                                onClick={() => removeRow(setParamsRows, rowIndex)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", background: "transparent", color: "#b91c1c", cursor: "pointer" }}
                                            >
                                                x
                                            </button>
                                        </div>
                                    ))}
                                </div>

                                <button
                                    type="button"
                                    onClick={() => addRow(setParamsRows)}
                                    style={{ width: "100%", border: "none", borderTop: "1px solid #edf2f8", background: "#f9fbfe", padding: "8px", cursor: "pointer", fontWeight: 600, color: "#0b4f6c" }}
                                >
                                    + Add Param
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "Headers" && (
                        <div style={{ marginTop: 12 }}>
                            <div
                                style={{
                                    border: "1px solid #c7d3e7",
                                    borderRadius: 8,
                                    overflow: "hidden",
                                    background: "#fff",
                                    fontSize: 12,
                                }}
                            >
                                <div style={{ display: "grid", gridTemplateColumns: TABLE_COLUMNS, background: "#f7fbff", fontWeight: 700, color: "#44516b" }}>
                                    <div style={{ padding: "8px" }}>On</div>
                                    <div style={{ padding: "8px" }}>Key</div>
                                    <div style={{ padding: "8px" }}>Value</div>
                                    <div style={{ padding: "8px" }}>Description</div>
                                    <div style={{ padding: "8px" }} />
                                </div>

                                <div style={{ maxHeight: "36vh", overflowY: "auto" }}>
                                    {headerRows.map((row, rowIndex) => (
                                        <div key={`header-${rowIndex}`} style={{ display: "grid", gridTemplateColumns: TABLE_COLUMNS, borderTop: "1px solid #edf2f8" }}>
                                            <div style={{ padding: "8px" }}>
                                                <input
                                                    type="checkbox"
                                                    checked={row.enabled}
                                                    onChange={(e) => updateRow(setHeaderRows, rowIndex, "enabled", e.target.checked)}
                                                />
                                            </div>
                                            <input
                                                value={row.key}
                                                onChange={(e) => updateRow(setHeaderRows, rowIndex, "key", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <input
                                                value={row.value}
                                                onChange={(e) => updateRow(setHeaderRows, rowIndex, "value", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <input
                                                value={row.description}
                                                onChange={(e) => updateRow(setHeaderRows, rowIndex, "description", e.target.value)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", padding: "8px" }}
                                            />
                                            <button
                                                type="button"
                                                onClick={() => removeRow(setHeaderRows, rowIndex)}
                                                style={{ border: "none", borderLeft: "1px solid #edf2f8", background: "transparent", color: "#b91c1c", cursor: "pointer" }}
                                            >
                                                x
                                            </button>
                                        </div>
                                    ))}
                                </div>

                                <button
                                    type="button"
                                    onClick={() => addRow(setHeaderRows)}
                                    style={{ width: "100%", border: "none", borderTop: "1px solid #edf2f8", background: "#f9fbfe", padding: "8px", cursor: "pointer", fontWeight: 600, color: "#0b4f6c" }}
                                >
                                    + Add Header
                                </button>
                            </div>
                        </div>
                    )}

                    {activeTab === "Body" && (
                        <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 12 }}>
                            <textarea
                                value={bodyInput}
                                onChange={(e) => setBodyInput(e.target.value)}
                                onBlur={() => setBodyInput((prev) => formatJsonIfPossible(prev))}
                                disabled={!canSendBody}
                                style={{
                                    width: "100%",
                                    minHeight: 260,
                                    border: "1px solid #c7d3e7",
                                    borderRadius: 8,
                                    padding: "10px 12px",
                                    boxSizing: "border-box",
                                    fontFamily: MONO_FONT,
                                    fontSize: 12,
                                    resize: "vertical",
                                    background: canSendBody ? "#fff" : "#f3f5f9",
                                }}
                            />
                        </div>
                    )}

                    {activeTab === "cURL" && (
                        <div style={{ marginTop: 12 }}>
                            <textarea
                                value={curlCommand}
                                readOnly
                                style={{
                                    width: "100%",
                                    minHeight: 260,
                                    border: "1px solid #c7d3e7",
                                    borderRadius: 8,
                                    padding: "10px 12px",
                                    boxSizing: "border-box",
                                    fontFamily: MONO_FONT,
                                    fontSize: 12,
                                    background: "#f8fafc",
                                }}
                            />
                        </div>
                    )}

                    {activeTab === "Import cURL" && (
                        <div style={{ marginTop: 12, display: "flex", flexDirection: "column", gap: 10 }}>
                            <textarea
                                value={importCurlText}
                                onChange={(e) => setImportCurlText(e.target.value)}
                                placeholder="Paste cURL here..."
                                style={{
                                    width: "100%",
                                    minHeight: 260,
                                    border: "1px solid #c7d3e7",
                                    borderRadius: 8,
                                    padding: "10px 12px",
                                    boxSizing: "border-box",
                                    fontFamily: MONO_FONT,
                                    fontSize: 12,
                                    background: "#fff",
                                }}
                            />

                            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                                <button
                                    type="button"
                                    onClick={parseCurlAndApply}
                                    style={{
                                        border: "1px solid #0b4f6c",
                                        background: "#0b4f6c",
                                        color: "#fff",
                                        borderRadius: 8,
                                        padding: "10px 12px",
                                        fontWeight: 700,
                                        cursor: "pointer",
                                    }}
                                >
                                    Import to Request
                                </button>

                                <span style={{ fontSize: 12, color: "#52627f" }}>{importMessage}</span>
                            </div>
                        </div>
                    )}

                    <div style={{ marginTop: 12 }}>
                        <div style={{ marginBottom: 6, fontSize: 12, fontWeight: 700, color: "#30415f" }}>Response</div>
                        <textarea
                            value={responsePreview}
                            readOnly
                            style={{
                                width: "100%",
                                minHeight: 180,
                                border: "1px solid #d7e1ef",
                                borderRadius: 8,
                                padding: "10px 12px",
                                boxSizing: "border-box",
                                fontFamily: MONO_FONT,
                                fontSize: 12,
                                background: "#ffffff",
                                color: "#2a3447",
                                resize: "vertical",
                            }}
                        />
                    </div>
                </section>
            </div>
        </main>
    );
}
